S_GAME.stage_get_enemy_num=function(n){var f=0,e=STAGE.length-1,i,t,r,u;if(n==null||n<=0||n>e){console.error("stage값 오류  in S_GAME.stage_get_enemy_num(): "+n);return}if(i=STAGE[n].WAVE.length-1,isNaN(i)||i==null||i<=0){console.error("wave값 오류 in S_GAME.stage_get_enemy_num(): stage:"+n+" wave_num:"+i);return}for(t=1;t<=i;t++)if(r=STAGE[n].WAVE[t].GROUP.length-1,isNaN(r)||r==null||r<=0){console.error("group값 오류 in S_GAME.stage_get_enemy_num(): stage:"+n+" wave:"+t+" group_num:"+r);return}for(t=1;t<=i;t++)for(r=STAGE[n].WAVE[t].GROUP.length-1,u=1;u<=r;u++)f+=STAGE[n].WAVE[t].GROUP[u].CH_NUM;return util.log("tot_enemy_num = "+f),f};S_GAME.stage_get_index_grid=function(n,t){for(var i=1;i<=108;i++){var r=S_GAME.stage_get_start_xy_grid(i),u=r.x,f=r.y,e=u+S_GAME.line.W,o=f+S_GAME.line.H;if(u<=n&&n<=e&&f<=t&&t<=o)return i}return 0};S_GAME.stage_get_start_xy_grid=function(n){for(var t,u,f,r=0,i=1;i<=S_GAME.line.row_len;i++)for(t=1;t<=S_GAME.line.col_len;t++)if(r++,u=S_GAME.line.start_x+(t-1)*S_GAME.line.W,f=S_GAME.line.start_y+(i-1)*S_GAME.line.H,r==n)return{x:u,y:f}};S_GAME.stage_is_exist_grid_index=function(n,t){var i=S_GAME.focus.hero,u,r;if(t=="영웅소환"&&(CAL.is_hero("드래곤 라이더",STORAGE.hero_selected[i])||CAL.is_hero("엘리야",STORAGE.hero_selected[i])||CAL.is_hero("안나",STORAGE.hero_selected[i])&&HERO_AWAKE.IS_awake(19)||CAL.is_hero("초대 황금맨",STORAGE.hero_selected[i])&&HERO_AWAKE.IS_awake(1)||HERO[STORAGE.hero_selected[i]].FLY==1))return!0;for(u=STAGE[S_GAME.stage].PATHSPOT.length-1,r=1;r<=u;r++)if(STAGE[S_GAME.stage].PATHSPOT[r]==n)return!0;return!1} 
